package com.company.skillplatform.version.domain;import static org.assertj.core.api.Assertions.*;import org.junit.jupiter.api.Test;
class SemanticVersionPolicyTest{private final SemanticVersionPolicy p=new SemanticVersionPolicy();@Test void calculatesVersionMatrix(){assertThat(p.candidate(ChangeType.INITIAL,null)).isEqualTo("1.0.0");assertThat(p.candidate(ChangeType.ONLINE_EDIT,"1.6.2")).isEqualTo("1.7.0");assertThat(p.candidate(ChangeType.ZIP_REUPLOAD,"1.6.2")).isEqualTo("2.0.0");assertThat(p.compare("2.0.0","1.9.9")).isPositive();assertThatThrownBy(()->p.candidate(ChangeType.ONLINE_EDIT,"bad")).isInstanceOf(RuntimeException.class);assertThatThrownBy(()->p.candidate(ChangeType.ONLINE_EDIT,"1.x.0")).isInstanceOf(RuntimeException.class);}}
